shell:
({
  movies:  db.movies.countDocuments(),
  ratings: db.ratings.countDocuments(),
  tags:    db.tags.countDocuments(),
  links:   db.links.countDocuments()
})

db.movies.updateMany({}, [
  {
    $set: {
      year: {
        $let: {
          vars: { m: { $regexFind: { input: "$title", regex: /\((\d{4})\)\s*$/ } } },
          in: {
            $cond: [
              { $eq: ["$$m", null] },
              null,
              { $toInt: { $arrayElemAt: ["$$m.captures", 0] } }
            ]
          }
        }
      }
    }
  }
])

db.movies.updateMany({}, [
  { $set: { genreList: { $split: ["$genres", "|"] } } }
])

db.ratings.updateMany({}, [
  { $set: { ratedAt: { $toDate: { $multiply: ["$timestamp", 1000] } } } }
]);
db.tags.updateMany({}, [
  { $set: { taggedAt: { $toDate: { $multiply: ["$timestamp", 1000] } } } }
])

db.movies.updateMany(
  { title: /, (The|A|An) \(/ },
  [
    {
      $set: {
        title: {
          $let: {
            vars: { m: { $regexFind: { input: "$title", regex: /^(.+), (The|A|An) (\(.+)$/ } } },
            in: {
              $concat: [
                { $arrayElemAt: ["$$m.captures", 1] }, " ",
                { $arrayElemAt: ["$$m.captures", 0] }, " ",
                { $arrayElemAt: ["$$m.captures", 2] }
              ]
            }
          }
        }
      }
    }
  ]
)

db.ratings.createIndex({ movieId: 1 });
db.ratings.createIndex({ userId: 1 });
db.tags.createIndex({ movieId: 1 });
db.movies.createIndex({ movieId: 1 }, { unique: true });
db.movies.createIndex({ genreList: 1 });
db.movies.createIndex({ year: 1 });
db.movies.createIndex({ title: "text" });
db.movies.getIndexes().map(i => i.name)

db.movies.aggregate([
  { $unwind: "$genreList" },
  { $group: { _id: "$genreList", movieCount: { $sum: 1 } } },
  { $sort: { movieCount: -1 } }
])

db.movies.aggregate([
  { $match: { year: { $ne: null } } },
  {
    $group: {
      _id: { $multiply: [{ $floor: { $divide: ["$year", 10] } }, 10] },
      movies: { $sum: 1 }
    }
  },
  { $sort: { _id: 1 } }
])

db.movies.aggregate([
  { $match: { year: { $ne: null } } },
  { $group: { _id: "$year", movies: { $sum: 1 } } },
  { $sort: { movies: -1 } },
  { $limit: 10 }
])

db.movies.aggregate([
  { $match: { genreList: { $not: { $size: 1 } } } },
  { $group: { _id: "$genres", count: { $sum: 1 } } },
  { $sort: { count: -1 } },
  { $limit: 10 }
])

db.ratings.aggregate([
  { $group: { _id: "$rating", count: { $sum: 1 } } },
  { $sort: { _id: 1 } }
])

db.ratings.aggregate([
  {
    $group: {
      _id: null,
      totalRatings: { $sum: 1 },
      avgRating: { $avg: "$rating" },
      minRating: { $min: "$rating" },
      maxRating: { $max: "$rating" },
      stdDev: { $stdDevPop: "$rating" }
    }
  },
  {
    $project: {
      _id: 0,
      totalRatings: 1,
      avgRating: { $round: ["$avgRating", 3] },
      minRating: 1,
      maxRating: 1,
      stdDev: { $round: ["$stdDev", 3] }
    }
  }
])

db.ratings.aggregate([
  { $match: { movieId: 1 } },
  {
    $group: {
      _id: "$movieId",
      ratings: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$movieId",
      ratingCount: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  { $sort: { ratingCount: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  {
    $project: {
      _id: 0,
      title: "$movie.title",
      ratingCount: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$movieId",
      ratingCount: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  { $match: { ratingCount: { $gte: 100 } } },
  { $sort: { avgRating: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  {
    $project: {
      _id: 0,
      title: "$movie.title",
      year: "$movie.year",
      ratingCount: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$movieId",
      ratingCount: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  { $match: { ratingCount: { $gte: 30 } } },
  { $sort: { avgRating: 1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  {
    $project: {
      _id: 0,
      title: "$movie.title",
      ratingCount: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$movieId",
      ratingCount: { $sum: 1 },
      avgRating: { $avg: "$rating" },
      stdDev: { $stdDevPop: "$rating" }
    }
  },
  { $match: { ratingCount: { $gte: 50 } } },
  { $sort: { stdDev: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  {
    $project: {
      _id: 0,
      title: "$movie.title",
      ratingCount: 1,
      avgRating: { $round: ["$avgRating", 2] },
      stdDev: { $round: ["$stdDev", 3] }
    }
  }
])

db.ratings.aggregate([
  { $match: { rating: 5 } },
  { $group: { _id: "$movieId", fiveStars: { $sum: 1 } } },
  { $sort: { fiveStars: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  { $project: { _id: 0, title: "$movie.title", fiveStars: 1 } }
])

db.movies.aggregate([
  {
    $lookup: {
      from: "ratings",
      localField: "movieId",
      foreignField: "movieId",
      as: "r"
    }
  },
  { $match: { r: { $size: 0 } } },
  { $count: "unratedMovies" }
])

db.ratings.aggregate([
  {
    $group: { _id: "$movieId", v: { $sum: 1 }, R: { $avg: "$rating" } }
  },
  { $match: { v: { $gte: 50 } } },
  {
    $addFields: {
      weighted: {
        $add: [
          {
            $multiply: [{ $divide: ["$v", { $add: ["$v", 50] }] }, "$R"]
          },
          {
            $multiply: [{ $divide: [50, { $add: ["$v", 50] }] }, 3.5]
          }
        ]
      }
    }
  },
  { $sort: { weighted: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  {
    $project: {
      _id: 0,
      title: "$movie.title",
      votes: "$v",
      avgRating: { $round: ["$R", 2] },
      weightedRating: { $round: ["$weighted", 3] }
    }
  }
])

db.movies.aggregate([
  {
    $lookup: {
      from: "ratings",
      localField: "movieId",
      foreignField: "movieId",
      as: "r"
    }
  },
  { $unwind: "$r" },
  { $unwind: "$genreList" },
  {
    $group: {
      _id: "$genreList",
      avgRating: { $avg: "$r.rating" },
      ratings: { $sum: 1 }
    }
  },
  {
    $project: { avgRating: { $round: ["$avgRating", 3] }, ratings: 1 }
  },
  { $sort: { avgRating: -1 } }
])

db.movies.aggregate([
  {
    $lookup: {
      from: "ratings",
      localField: "movieId",
      foreignField: "movieId",
      as: "r"
    }
  },
  { $project: { genreList: 1, n: { $size: "$r" } } },
  { $unwind: "$genreList" },
  { $group: { _id: "$genreList", ratings: { $sum: "$n" } } },
  { $sort: { ratings: -1 } },
  { $limit: 10 }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$movieId",
      ratingCount: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  { $match: { ratingCount: { $gte: 50 } } },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  { $unwind: "$movie.genreList" },
  { $sort: { avgRating: -1 } },
  {
    $group: {
      _id: "$movie.genreList",
      bestMovie: { $first: "$movie.title" },
      avgRating: { $first: { $round: ["$avgRating", 2] } },
      ratingCount: { $first: "$ratingCount" }
    }
  },
  { $sort: { _id: 1 } }
])

db.movies.aggregate([
  {
    $match: {
      year: { $gte: 1970 },
      genreList: { $in: ["Action", "Drama", "Comedy"] }
    }
  },
  { $unwind: "$genreList" },
  { $match: { genreList: { $in: ["Action", "Drama", "Comedy"] } } },
  {
    $group: {
      _id: {
        decade: { $multiply: [{ $floor: { $divide: ["$year", 10] } }, 10] },
        genre: "$genreList"
      },
      movies: { $sum: 1 }
    }
  },
  { $sort: { "_id.decade": 1, "_id.genre": 1 } }
])

db.movies.aggregate([
  { $project: { genreCount: { $size: "$genreList" } } },
  {
    $group: {
      _id: null,
      avgGenres: { $avg: "$genreCount" },
      maxGenres: { $max: "$genreCount" }
    }
  },
  {
    $project: {
      _id: 0,
      avgGenres: { $round: ["$avgGenres", 2] },
      maxGenres: 1
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$userId",
      ratings: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  { $sort: { ratings: -1 } },
  { $limit: 10 },
  {
    $project: {
      userId: "$_id",
      _id: 0,
      ratings: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$userId",
      ratings: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  { $match: { ratings: { $gte: 100 } } },
  {
    $project: {
      userId: "$_id",
      _id: 0,
      ratings: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  },
  {
    $facet: {
      harshest: [{ $sort: { avgRating: 1 } }, { $limit: 5 }],
      mostGenerous: [{ $sort: { avgRating: -1 } }, { $limit: 5 }]
    }
  }
])

db.ratings.aggregate([
  { $group: { _id: "$userId", ratings: { $sum: 1 } } },
  {
    $bucket: {
      groupBy: "$ratings",
      boundaries: [20, 50, 100, 200, 500, 1000, 3000],
      default: "3000+",
      output: { users: { $sum: 1 } }
    }
  }
])

db.ratings.aggregate([
  { $match: { userId: 1 } },
  {
    $lookup: {
      from: "movies",
      localField: "movieId",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  { $unwind: "$movie.genreList" },
  {
    $group: {
      _id: "$movie.genreList",
      rated: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  {
    $project: { rated: 1, avgRating: { $round: ["$avgRating", 2] } }
  },
  { $sort: { rated: -1 } },
  { $limit: 5 }
])

db.ratings.aggregate([
  {
    $group: {
      _id: { $year: "$ratedAt" },
      ratings: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  {
    $project: { ratings: 1, avgRating: { $round: ["$avgRating", 2] } }
  },
  { $sort: { _id: 1 } }
]).toArray()

db.ratings.aggregate([
  {
    $group: { _id: { $dayOfWeek: "$ratedAt" }, ratings: { $sum: 1 } }
  },
  { $sort: { _id: 1 } },
  {
    $project: {
      _id: 0,
      day: {
        $arrayElemAt: [
          ["", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
          "$_id"
        ]
      },
      ratings: 1
    }
  }
])

db.ratings.aggregate([
  { $match: { userId: 414 } },
  {
    $group: {
      _id: "$userId",
      firstRating: { $min: "$ratedAt" },
      lastRating: { $max: "$ratedAt" },
      total: { $sum: 1 }
    }
  }
])

db.tags.aggregate([
  { $group: { _id: { $toLower: "$tag" }, count: { $sum: 1 } } },
  { $sort: { count: -1 } },
  { $limit: 15 }
])

db.tags.aggregate([
  { $match: { movieId: 296 } },
  {
    $group: {
      _id: "$movieId",
      tags: { $addToSet: "$tag" },
      taggers: { $addToSet: "$userId" }
    }
  },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  {
    $project: {
      _id: 0,
      title: { $first: "$movie.title" },
      totalTags: { $size: "$tags" },
      taggerCount: { $size: "$taggers" },
      sampleTags: { $slice: ["$tags", 15] }
    }
  }
])

db.tags.aggregate([
  { $group: { _id: "$movieId", tagCount: { $sum: 1 } } },
  { $sort: { tagCount: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  { $project: { _id: 0, title: "$movie.title", tagCount: 1 } }
])

db.tags.aggregate([
  { $match: { tag: { $regex: "^funny$", $options: "i" } } },
  { $group: { _id: "$movieId" } },
  {
    $lookup: {
      from: "ratings",
      localField: "_id",
      foreignField: "movieId",
      as: "r"
    }
  },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  {
    $project: {
      _id: 0,
      title: { $first: "$movie.title" },
      ratings: { $size: "$r" },
      avgRating: { $round: [{ $avg: "$r.rating" }, 2] }
    }
  },
  { $sort: { ratings: -1 } },
  { $limit: 10 }
])

db.tags.aggregate([
  {
    $group: {
      _id: "$userId",
      tags: { $sum: 1 },
      movies: { $addToSet: "$movieId" }
    }
  },
  {
    $project: {
      userId: "$_id",
      _id: 0,
      tags: 1,
      moviesTagged: { $size: "$movies" }
    }
  },
  { $sort: { tags: -1 } },
  { $limit: 5 }
])

db.movies.aggregate([
  { $match: { movieId: { $ne: 1 } } },
  {
    $addFields: {
      sharedGenres: {
        $size: {
          $setIntersection: [
            "$genreList",
            [
              "Adventure",
              "Animation",
              "Children",
              "Comedy",
              "Fantasy"
            ]
          ]
        }
      }
    }
  },
  { $match: { sharedGenres: { $gte: 4 } } },
  {
    $lookup: {
      from: "ratings",
      localField: "movieId",
      foreignField: "movieId",
      as: "r"
    }
  },
  {
    $addFields: {
      ratingCount: { $size: "$r" },
      avgRating: { $avg: "$r.rating" }
    }
  },
  { $match: { ratingCount: { $gte: 20 } } },
  { $sort: { sharedGenres: -1, avgRating: -1 } },
  { $limit: 10 },
  {
    $project: {
      _id: 0,
      title: 1,
      sharedGenres: 1,
      ratingCount: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  }
])

db.ratings.aggregate([
  { $match: { movieId: 2571, rating: { $gte: 4.5 } } },
  { $group: { _id: null, fans: { $addToSet: "$userId" } } },
  {
    $lookup: {
      from: "ratings",
      let: { fans: "$fans" },
      pipeline: [
        {
          $match: {
            $expr: {
              $and: [
                { $in: ["$userId", "$$fans"] },
                { $gte: ["$rating", 4.5] },
                { $ne: ["$movieId", 2571] }
              ]
            }
          }
        },
        { $group: { _id: "$movieId", fanCount: { $sum: 1 } } },
        { $sort: { fanCount: -1 } },
        { $limit: 10 }
      ],
      as: "alsoLiked"
    }
  },
  { $unwind: "$alsoLiked" },
  {
    $lookup: {
      from: "movies",
      localField: "alsoLiked._id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  {
    $project: {
      _id: 0,
      title: { $first: "$movie.title" },
      fansWhoLikedIt: "$alsoLiked.fanCount",
      totalMatrixFans: { $size: "$fans" }
    }
  }
])

db.movies.aggregate([
  { $match: { genreList: { $all: ["Action", "Adventure"] } } },
  {
    $lookup: {
      from: "ratings",
      localField: "movieId",
      foreignField: "movieId",
      as: "r"
    }
  },
  { $match: { "r.userId": { $ne: 1 } } },
  {
    $addFields: {
      ratingCount: { $size: "$r" },
      avgRating: { $avg: "$r.rating" }
    }
  },
  { $match: { ratingCount: { $gte: 50 } } },
  { $sort: { avgRating: -1 } },
  { $limit: 10 },
  {
    $project: {
      _id: 0,
      title: 1,
      year: 1,
      ratingCount: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$movieId",
      ratingCount: { $sum: 1 },
      avgRating: { $avg: "$rating" }
    }
  },
  {
    $match: { ratingCount: { $gte: 10, $lte: 30 }, avgRating: { $gte: 4.3 } }
  },
  { $sort: { avgRating: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  {
    $project: {
      _id: 0,
      title: "$movie.title",
      genres: "$movie.genres",
      ratingCount: 1,
      avgRating: { $round: ["$avgRating", 2] }
    }
  }
])

db.ratings.aggregate([
  {
    $group: {
      _id: "$movieId",
      ratingCount: { $sum: 1 },
      avgRating: { $avg: "$rating" },
      stdDev: { $stdDevPop: "$rating" }
    }
  },
  { $merge: { into: "movie_stats", whenMatched: "replace" } }
]);
db.movie_stats.find().sort({ ratingCount: -1 }).limit(5)

db.ratings.aggregate([
  {
    $facet: {
      overall: [
        {
          $group: {
            _id: null,
            ratings: { $sum: 1 },
            avg: { $avg: "$rating" }
          }
        },
        {
          $project: { _id: 0, ratings: 1, avg: { $round: ["$avg", 2] } }
        }
      ],
      topMovies: [
        { $group: { _id: "$movieId", n: { $sum: 1 } } },
        { $sort: { n: -1 } },
        { $limit: 3 }
      ],
      topUsers: [
        { $group: { _id: "$userId", n: { $sum: 1 } } },
        { $sort: { n: -1 } },
        { $limit: 3 }
      ],
      byStar: [
        { $group: { _id: "$rating", n: { $sum: 1 } } },
        { $sort: { _id: -1 } }
      ]
    }
  }
])

db.movies.updateOne(
  { movieId: 999999 },
  { $push: { genreList: "Drama" }, $set: { genres: "Documentary|Sci-Fi|Drama", verified: true } }
);
db.movies.findOne({ movieId: 999999 })

const plan = db.ratings.find({ movieId: 296 }).explain("executionStats");
({
  stage: plan.queryPlanner.winningPlan.stage,
  inputStage: plan.queryPlanner.winningPlan.inputStage?.stage,
  indexName: plan.queryPlanner.winningPlan.inputStage?.indexName,
  docsReturned: plan.executionStats.nReturned,
  docsExamined: plan.executionStats.totalDocsExamined,
  keysExamined: plan.executionStats.totalKeysExamined,
  executionTimeMs: plan.executionStats.executionTimeMillis
})
